'use client';

import { useMemo } from 'react';
import { formatMoney, formatPercent, formatPrice, roundToTick } from '../../format';
import { useInstrument } from '../../theme/theme-provider';
import type { Instrument, Side } from '../../types';
import { cn } from '../../utils';
import { Button } from '../ui/button';
import { Label } from '../ui/label';
import { NumberField } from './number-field';

export interface BracketValue {
  stopLoss: number | null;
  takeProfit: number | null;
}

export interface BracketFieldsProps {
  side: Side;
  entryPrice: number;
  quantity: number;
  value: BracketValue;
  onChange: (value: BracketValue) => void;
  instrument?: Partial<Instrument>;
  /** Quick stop distances as a fraction of entry, e.g. 0.01 is 1%. */
  presets?: number[];
  className?: string;
}

/**
 * Stop loss and take profit, with the risk/reward the pair actually implies.
 *
 * The R:R number is the point of the component. Traders set a stop and a
 * target separately and then never do the division, which is how a 0.4:1 trade
 * gets placed on purpose. Both legs are validated against the side: a stop
 * above entry on a long is not a stop, it is a second target.
 */
export function BracketFields({
  side,
  entryPrice,
  quantity,
  value,
  onChange,
  instrument,
  presets = [0.005, 0.01, 0.02, 0.05],
  className,
}: BracketFieldsProps) {
  const inst = useInstrument(instrument);
  const isBuy = side === 'buy';
  const { stopLoss, takeProfit } = value;

  const analysis = useMemo(() => {
    const risk =
      stopLoss !== null ? (isBuy ? entryPrice - stopLoss : stopLoss - entryPrice) : null;
    const reward =
      takeProfit !== null ? (isBuy ? takeProfit - entryPrice : entryPrice - takeProfit) : null;
    return {
      risk,
      reward,
      riskMoney: risk !== null ? risk * quantity : null,
      rewardMoney: reward !== null ? reward * quantity : null,
      ratio: risk && reward && risk > 0 ? reward / risk : null,
      stopWrongSide: risk !== null && risk <= 0,
      targetWrongSide: reward !== null && reward <= 0,
    };
  }, [stopLoss, takeProfit, entryPrice, quantity, isBuy]);

  const applyPreset = (fraction: number) => {
    const stop = isBuy ? entryPrice * (1 - fraction) : entryPrice * (1 + fraction);
    const target = isBuy ? entryPrice * (1 + fraction * 2) : entryPrice * (1 - fraction * 2);
    onChange({
      stopLoss: roundToTick(stop, inst.tickSize),
      takeProfit: roundToTick(target, inst.tickSize),
    });
  };

  return (
    <div className={cn('flex flex-col gap-2.5', className)}>
      <div className="flex items-center justify-between">
        <Label>Bracket</Label>
        <div className="flex gap-1">
          {presets.map((p) => (
            <Button
              key={p}
              size="xs"
              variant="ghost"
              onClick={() => applyPreset(p)}
              title={`Stop ${formatPercent(p, 1, false)} away, target 2R`}
            >
              {formatPercent(p, p < 0.01 ? 1 : 0, false)}
            </Button>
          ))}
          {(stopLoss !== null || takeProfit !== null) && (
            <Button
              size="xs"
              variant="ghost"
              onClick={() => onChange({ stopLoss: null, takeProfit: null })}
            >
              Clear
            </Button>
          )}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-2">
        <NumberField
          label="Stop loss"
          value={stopLoss}
          onChange={(v) =>
            onChange({ ...value, stopLoss: v === null ? null : roundToTick(v, inst.tickSize) })
          }
          step={inst.tickSize}
          min={0}
          suffix={inst.currency}
          invalid={analysis.stopWrongSide}
        />
        <NumberField
          label="Take profit"
          value={takeProfit}
          onChange={(v) =>
            onChange({ ...value, takeProfit: v === null ? null : roundToTick(v, inst.tickSize) })
          }
          step={inst.tickSize}
          min={0}
          suffix={inst.currency}
          invalid={analysis.targetWrongSide}
        />
      </div>

      {(analysis.risk !== null || analysis.reward !== null) && (
        <dl className="bg-muted flex flex-col gap-1 rounded-md border p-2.5 text-[11px]">
          {analysis.riskMoney !== null && (
            <div className="flex justify-between gap-3">
              <dt className="text-muted-foreground">Risk</dt>
              <dd className={cn('font-mono tabular-nums', analysis.stopWrongSide ? 'text-destructive' : 'text-down')}>
                {analysis.stopWrongSide
                  ? `Stop must be ${isBuy ? 'below' : 'above'} ${formatPrice(entryPrice, inst.pricePrecision)}`
                  : formatMoney(Math.abs(analysis.riskMoney), inst.currency)}
              </dd>
            </div>
          )}
          {analysis.rewardMoney !== null && (
            <div className="flex justify-between gap-3">
              <dt className="text-muted-foreground">Reward</dt>
              <dd className={cn('font-mono tabular-nums', analysis.targetWrongSide ? 'text-destructive' : 'text-up')}>
                {analysis.targetWrongSide
                  ? `Target must be ${isBuy ? 'above' : 'below'} ${formatPrice(entryPrice, inst.pricePrecision)}`
                  : formatMoney(Math.abs(analysis.rewardMoney), inst.currency)}
              </dd>
            </div>
          )}
          {analysis.ratio !== null && (
            <div className="flex items-center justify-between gap-3 border-t pt-1">
              <dt className="text-muted-foreground">Risk / reward</dt>
              <dd
                className={cn(
                  'font-mono font-semibold tabular-nums',
                  analysis.ratio >= 2 ? 'text-up' : analysis.ratio >= 1 ? 'text-foreground' : 'text-warn',
                )}
              >
                1 : {analysis.ratio.toFixed(2)}
              </dd>
            </div>
          )}
        </dl>
      )}
    </div>
  );
}

export interface LeverageSliderProps {
  value: number;
  onChange: (value: number) => void;
  max?: number;
  /** Leverage at or above this is flagged. */
  warnAt?: number;
  steps?: number[];
  className?: string;
}

/**
 * Leverage selector.
 *
 * The liquidation distance is shown next to the multiplier, because "20x" is
 * an abstraction and "4.8% against you and you are out" is the actual fact
 * being chosen.
 */
export function LeverageSlider({
  value,
  onChange,
  max = 100,
  warnAt = 20,
  steps = [1, 2, 5, 10, 20, 50, 100],
  className,
}: LeverageSliderProps) {
  const liquidationDistance = value > 0 ? 1 / value : 1;
  const hot = value >= warnAt;

  return (
    <div className={cn('flex flex-col gap-2', className)}>
      <div className="flex items-baseline justify-between">
        <Label>Leverage</Label>
        <span className="font-mono text-[11px] tabular-nums">
          <span className={cn('font-semibold', hot ? 'text-warn' : 'text-foreground')}>
            {value}×
          </span>
          <span className="text-muted-foreground">
            {' '}
            · liquidation {formatPercent(liquidationDistance, 1, false)} away
          </span>
        </span>
      </div>
      <div className="flex gap-1">
        {steps
          .filter((s) => s <= max)
          .map((step) => (
            <Button
              key={step}
              size="xs"
              variant={value === step ? 'secondary' : 'ghost'}
              aria-pressed={value === step}
              onClick={() => onChange(step)}
              className={cn('flex-1 font-mono tabular-nums', step >= warnAt && 'text-warn')}
            >
              {step}×
            </Button>
          ))}
      </div>
    </div>
  );
}

'use client';

import { ChevronDownIcon, ChevronUpIcon } from 'lucide-react';
import { useEffect, useId, useState } from 'react';
import { decimalsOf } from '../../format';
import { cn } from '../../utils';
import { Label } from '../ui/label';

export interface NumberFieldProps {
  value: number | null;
  onChange: (value: number | null) => void;
  label?: string;
  /** Unit rendered inside the field, e.g. `USD` or `shares`. */
  suffix?: string;
  step?: number;
  min?: number;
  max?: number;
  /** Decimals to snap to. Defaults to the decimals implied by `step`. */
  precision?: number;
  placeholder?: string;
  disabled?: boolean;
  readOnly?: boolean;
  hideStepper?: boolean;
  /** Marks the field invalid for assistive tech and tints the border. */
  invalid?: boolean;
  className?: string;
}

/**
 * Numeric entry for prices and quantities.
 *
 * Two things most number inputs get wrong, fixed here:
 *
 * 1. The raw string is kept while focused, so typing `1.` or `0.0` is not
 *    rewritten out from under the cursor mid-keystroke. Only a clamped,
 *    rounded number is ever committed.
 * 2. It is `type="text"` with `inputMode="decimal"`, not `type="number"`. A
 *    real number input silently changes value on mouse wheel - one stray
 *    scroll over a price field is a wrong order - and parses by locale.
 *
 * Arrow keys step by `step`; shift-arrow by ten.
 */
export function NumberField({
  value,
  onChange,
  label,
  suffix,
  step = 1,
  min,
  max,
  precision,
  placeholder,
  disabled = false,
  readOnly = false,
  hideStepper = false,
  invalid = false,
  className,
}: NumberFieldProps) {
  const id = useId();
  const decimals = precision ?? decimalsOf(step);
  const [draft, setDraft] = useState(() => (value === null ? '' : String(value)));
  const [editing, setEditing] = useState(false);

  // While the user is typing, the draft is the source of truth.
  useEffect(() => {
    if (!editing) setDraft(value === null ? '' : value.toFixed(decimals));
  }, [value, decimals, editing]);

  const clamp = (n: number) => {
    let out = n;
    if (min !== undefined) out = Math.max(min, out);
    if (max !== undefined) out = Math.min(max, out);
    return Number(out.toFixed(decimals));
  };

  const commit = (text: string) => {
    const trimmed = text.trim();
    if (trimmed === '' || trimmed === '-' || trimmed === '.') {
      onChange(null);
      setDraft('');
      return;
    }
    const parsed = Number(trimmed);
    if (!Number.isFinite(parsed)) {
      setDraft(value === null ? '' : value.toFixed(decimals));
      return;
    }
    const next = clamp(parsed);
    onChange(next);
    setDraft(next.toFixed(decimals));
  };

  const bump = (multiplier: number) => {
    const base = value ?? min ?? 0;
    const next = clamp(base + step * multiplier);
    onChange(next);
    setDraft(next.toFixed(decimals));
  };

  return (
    <div className={cn('group flex min-w-0 flex-col gap-1', className)}>
      {label && <Label htmlFor={id}>{label}</Label>}
      <div
        data-slot="number-field"
        className={cn(
          'border-input bg-background flex h-9 items-stretch overflow-hidden rounded-md border shadow-xs transition-[color,box-shadow]',
          'focus-within:border-ring focus-within:ring-ring/50 focus-within:ring-[3px]',
          invalid && 'border-destructive focus-within:ring-destructive/20',
          disabled && 'pointer-events-none opacity-50',
        )}
      >
        <input
          id={id}
          type="text"
          inputMode="decimal"
          autoComplete="off"
          spellCheck={false}
          aria-invalid={invalid || undefined}
          className="text-foreground placeholder:text-muted-foreground/70 min-w-0 flex-1 bg-transparent px-2 text-right font-mono text-sm tabular-nums outline-none"
          value={draft}
          placeholder={placeholder}
          disabled={disabled}
          readOnly={readOnly}
          onFocus={() => setEditing(true)}
          onChange={(e) => {
            const next = e.target.value;
            if (/^-?\d*\.?\d*$/.test(next)) setDraft(next);
          }}
          onBlur={() => {
            setEditing(false);
            commit(draft);
          }}
          onKeyDown={(e) => {
            if (readOnly || disabled) return;
            if (e.key === 'ArrowUp') {
              e.preventDefault();
              bump(e.shiftKey ? 10 : 1);
            } else if (e.key === 'ArrowDown') {
              e.preventDefault();
              bump(e.shiftKey ? -10 : -1);
            } else if (e.key === 'Enter') {
              commit(draft);
            }
          }}
        />
        {suffix && (
          <span className="text-muted-foreground bg-muted flex items-center border-l px-2 text-[10px]">
            {suffix}
          </span>
        )}
        {!hideStepper && !readOnly && (
          <div className="flex flex-col border-l">
            <button
              type="button"
              aria-label="Increase"
              // Not a tab stop: arrow keys already do this from the input, and
              // two extra stops per field makes a ticket slow to tab through.
              tabIndex={-1}
              disabled={disabled}
              className="text-muted-foreground hover:bg-accent hover:text-foreground flex flex-1 cursor-pointer items-center justify-center border-b px-1"
              onClick={() => bump(1)}
            >
              <ChevronUpIcon className="size-3" />
            </button>
            <button
              type="button"
              aria-label="Decrease"
              tabIndex={-1}
              disabled={disabled}
              className="text-muted-foreground hover:bg-accent hover:text-foreground flex flex-1 cursor-pointer items-center justify-center px-1"
              onClick={() => bump(-1)}
            >
              <ChevronDownIcon className="size-3" />
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { Slot } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import type { ComponentProps } from 'react';
import { cn } from '../../utils';

/**
 * shadcn/ui's Button, plus the two variants a trading surface cannot do
 * without: `buy` and `sell`. They read from the direction tokens, so they
 * follow the active palette instead of hardcoding green and red.
 */
const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-[color,box-shadow,background-color] disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 aria-invalid:border-destructive cursor-pointer",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground shadow-xs hover:bg-primary/90',
        destructive:
          'bg-destructive text-destructive-foreground shadow-xs hover:bg-destructive/90 focus-visible:ring-destructive/20',
        outline:
          'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground',
        secondary: 'bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        link: 'text-primary underline-offset-4 hover:underline',
        buy: 'bg-up text-up-foreground shadow-xs hover:bg-up/90 focus-visible:ring-up/40',
        sell: 'bg-down text-down-foreground shadow-xs hover:bg-down/90 focus-visible:ring-down/40',
      },
      size: {
        default: 'h-9 px-4 py-2 has-[>svg]:px-3',
        sm: 'h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5',
        xs: 'h-6 rounded-sm gap-1 px-2 text-[11px]',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
      },
      block: { true: 'w-full', false: '' },
    },
    defaultVariants: { variant: 'default', size: 'default', block: false },
  },
);

export interface ButtonProps
  extends ComponentProps<'button'>,
    VariantProps<typeof buttonVariants> {
  /** Render as the child element (Radix Slot) instead of a `<button>`. */
  asChild?: boolean;
}

function Button({ className, variant, size, block, asChild = false, ...props }: ButtonProps) {
  const Comp = asChild ? Slot : 'button';
  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, block, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };

'use client';

import * as LabelPrimitive from '@radix-ui/react-label';
import type { ComponentProps } from 'react';
import { cn } from '../../utils';

/** Radix Label: clicking it focuses the control, including custom inputs. */
function Label({ className, ...props }: ComponentProps<typeof LabelPrimitive.Root>) {
  return (
    <LabelPrimitive.Root
      data-slot="label"
      className={cn(
        'text-muted-foreground flex items-center gap-1 text-[10px] font-medium tracking-wider uppercase select-none',
        'group-data-[disabled=true]:pointer-events-none group-data-[disabled=true]:opacity-50',
        className,
      )}
      {...props}
    />
  );
}

export { Label };

import type { Direction } from './types';

/**
 * Formatting helpers. Every number shown in a trading UI is formatted the same
 * way twice: fixed decimals so digits line up in a tabular-nums column, and an
 * explicit sign where direction matters.
 */

const cache = new Map<string, Intl.NumberFormat>();

function nf(min: number, max: number, extra?: Intl.NumberFormatOptions) {
  const key = `${min}:${max}:${extra ? JSON.stringify(extra) : ''}`;
  let f = cache.get(key);
  if (!f) {
    f = new Intl.NumberFormat('en-US', {
      minimumFractionDigits: min,
      maximumFractionDigits: max,
      ...extra,
    });
    cache.set(key, f);
  }
  return f;
}

/** `1234.5` at precision 2 -> `"1,234.50"`. */
export function formatPrice(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  return nf(precision, precision).format(value);
}

/** Quantity: grouped, trailing zeros trimmed. */
export function formatQuantity(value: number, precision = 0): string {
  if (!Number.isFinite(value)) return '--';
  return nf(0, precision).format(value);
}

/** `1250000` -> `"1.25M"`. Keeps size columns to four glyphs. */
export function formatCompact(value: number, digits = 2): string {
  if (!Number.isFinite(value)) return '--';
  const abs = Math.abs(value);
  const sign = value < 0 ? '-' : '';
  const units: Array<[number, string]> = [
    [1e12, 'T'],
    [1e9, 'B'],
    [1e6, 'M'],
    [1e3, 'K'],
  ];
  for (const [scale, suffix] of units) {
    if (abs >= scale) {
      const scaled = abs / scale;
      // Keep three significant digits: 1.25M, 12.5M, 125M.
      const d = scaled >= 100 ? 0 : scaled >= 10 ? 1 : digits;
      return `${sign}${nf(0, d).format(scaled)}${suffix}`;
    }
  }
  return `${sign}${nf(0, abs < 1 ? digits : 0).format(abs)}`;
}

/** `0.0421` -> `"+4.21%"`. Input is a ratio, not percentage points. */
export function formatPercent(ratio: number, precision = 2, signed = true): string {
  if (!Number.isFinite(ratio)) return '--';
  const pct = ratio * 100;
  const sign = signed && pct > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(pct)}%`;
}

/** Absolute change with a forced sign so gains and losses align. */
export function formatSigned(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(value)}`;
}

/** `hh:mm:ss` in local time - the tape's only useful resolution. */
export function formatTime(time: number | Date, withMillis = false): string {
  const d = time instanceof Date ? time : new Date(time);
  const base = d.toTimeString().slice(0, 8);
  if (!withMillis) return base;
  return `${base}.${String(d.getMilliseconds()).padStart(3, '0')}`;
}

/** Axis-friendly timestamp: drops seconds, adds the date when it changes. */
export function formatAxisTime(time: number, showDate = false): string {
  const d = new Date(time);
  const hhmm = d.toTimeString().slice(0, 5);
  if (!showDate) return hhmm;
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

/** Signed money, e.g. `-$1,204.50`. */
export function formatMoney(value: number, currency = '$', precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value < 0 ? '-' : '';
  return `${sign}${currency}${nf(precision, precision).format(Math.abs(value))}`;
}

/** Direction of `value` relative to `reference` (default zero). */
export function directionOf(value: number, reference = 0): Direction {
  if (!Number.isFinite(value) || value === reference) return 'flat';
  return value > reference ? 'up' : 'down';
}

/** The `tu-up` / `tu-down` / `tu-flat` class for a direction. */
export function directionClass(direction: Direction): string {
  return `tu-${direction}`;
}

/** `+` / `-` glyphs used by DeltaBadge and the tape. */
export function directionArrow(direction: Direction): string {
  return direction === 'up' ? '▲' : direction === 'down' ? '▼' : '–';
}

/** Round to the instrument's tick so UI-entered prices are always valid. */
export function roundToTick(price: number, tickSize: number): number {
  if (!tickSize || tickSize <= 0) return price;
  const ticks = Math.round(price / tickSize);
  // Re-round after dividing to shake off float dust (0.1 * 3 = 0.30000000000000004).
  const decimals = decimalsOf(tickSize);
  return Number((ticks * tickSize).toFixed(decimals));
}

/** Decimal places implied by a tick size: `0.01` -> 2, `0.5` -> 1, `5` -> 0. */
export function decimalsOf(tickSize: number): number {
  if (!Number.isFinite(tickSize) || tickSize <= 0) return 2;
  const s = tickSize.toString();
  if (s.includes('e-')) return Number(s.split('e-')[1]);
  const dot = s.indexOf('.');
  return dot === -1 ? 0 : s.length - dot - 1;
}

/** Shared domain types. Deliberately plain so any feed can map onto them. */

export type Side = 'buy' | 'sell';
export type Direction = 'up' | 'down' | 'flat';

/** One OHLCV bar. `time` is epoch milliseconds at the bar's open. */
export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

/** A single price level in the book. */
export interface BookLevel {
  price: number;
  size: number;
}

export interface OrderBookSnapshot {
  /** Highest price first. */
  bids: BookLevel[];
  /** Lowest price first. */
  asks: BookLevel[];
}

export interface Trade {
  id: string;
  time: number;
  price: number;
  size: number;
  /** Aggressor side: `buy` means it lifted the offer. */
  side: Side;
}

export interface Quote {
  symbol: string;
  name?: string;
  last: number;
  /** Previous session close, used for the day change. */
  prevClose: number;
  bid?: number;
  ask?: number;
  dayHigh?: number;
  dayLow?: number;
  volume?: number;
  /** Optional intraday series for an inline sparkline. */
  history?: number[];
}

export interface Position {
  symbol: string;
  /** Signed: negative is short. */
  quantity: number;
  avgPrice: number;
  markPrice: number;
}

export type OrderType = 'market' | 'limit' | 'stop' | 'stop-limit';
export type OrderStatus = 'working' | 'filled' | 'partial' | 'cancelled' | 'rejected';

export interface OrderDraft {
  symbol: string;
  side: Side;
  type: OrderType;
  quantity: number;
  /** Required for limit / stop-limit. */
  limitPrice?: number;
  /** Required for stop / stop-limit. */
  stopPrice?: number;
  timeInForce: TimeInForce;
}

export type TimeInForce = 'day' | 'gtc' | 'ioc' | 'fok';

export interface Order extends OrderDraft {
  id: string;
  time: number;
  status: OrderStatus;
  filledQuantity: number;
  avgFillPrice?: number;
}

/** Price/size formatting rules for an instrument. */
export interface Instrument {
  symbol: string;
  name?: string;
  /** Decimal places for price. */
  pricePrecision: number;
  /** Minimum price increment. */
  tickSize: number;
  /** Decimal places for quantity. */
  sizePrecision?: number;
  /** Quote-currency symbol, e.g. "$". */
  currency?: string;
}

/**
 * One execution. Distinct from an `Order`: an order is an instruction, a fill
 * is what actually happened to it, and a single order can produce many fills
 * at different prices. Reconciliation, cost basis and fee accounting all work
 * off fills, never off orders.
 */
export interface Fill {
  id: string;
  /** The order this execution belongs to, for grouping a partial sequence. */
  orderId?: string;
  symbol: string;
  time: number;
  side: Side;
  quantity: number;
  price: number;
  /** Commission or exchange fee, in the quote currency. Negative is a rebate. */
  fee?: number;
  /** `maker` rested and was hit; `taker` crossed the spread. Drives the fee. */
  liquidity?: 'maker' | 'taker';
  venue?: string;
}

'use client';

import {
  createContext,
  useContext,
  useMemo,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { TooltipProvider } from '../components/ui/tooltip';
import type { Instrument } from '../types';
import { cn } from '../utils';

export type ThemeName = 'dark' | 'light';
export type DirectionPalette = 'classic' | 'colorblind';

export interface TradingTheme {
  theme: ThemeName;
  /** `classic` is green/red; `colorblind` is blue/amber. */
  palette: DirectionPalette;
  /** Formatting defaults for components not given their own instrument. */
  instrument: Instrument;
}

export const defaultInstrument: Instrument = {
  symbol: '',
  pricePrecision: 2,
  tickSize: 0.01,
  sizePrecision: 0,
  currency: '$',
};

const ThemeContext = createContext<TradingTheme>({
  theme: 'dark',
  palette: 'classic',
  instrument: defaultInstrument,
});

export function useTradingTheme(): TradingTheme {
  return useContext(ThemeContext);
}

/**
 * Resolves the instrument a component formats with: its own prop wins, then
 * the provider's, then the library default.
 */
export function useInstrument(override?: Partial<Instrument>): Instrument {
  const { instrument } = useTradingTheme();
  return useMemo(
    () => (override ? { ...instrument, ...override } : instrument),
    [instrument, override],
  );
}

export interface TradingProviderProps {
  children: ReactNode;
  theme?: ThemeName;
  palette?: DirectionPalette;
  instrument?: Partial<Instrument>;
  /** Token overrides, e.g. `{ '--primary': '#ff8a00' }`. */
  tokens?: Record<string, string>;
  /**
   * Skip the wrapper element and inherit whatever theme the host already
   * applies. Use this inside an existing shadcn app that owns `.dark` itself.
   */
  inherit?: boolean;
  className?: string;
  style?: CSSProperties;
}

/**
 * Scopes theme, direction palette and instrument defaults to a subtree.
 *
 * Deliberately not a global stylesheet switch: two providers can coexist, so a
 * light-themed report can sit inside a dark terminal. Also mounts a single
 * Radix TooltipProvider so every tooltip in the tree shares one delay timer.
 */
export function TradingProvider({
  children,
  theme = 'dark',
  palette = 'classic',
  instrument,
  tokens,
  inherit = false,
  className,
  style,
}: TradingProviderProps) {
  const value = useMemo<TradingTheme>(
    () => ({ theme, palette, instrument: { ...defaultInstrument, ...instrument } }),
    [theme, palette, instrument],
  );

  const content = <TooltipProvider>{children}</TooltipProvider>;

  return (
    <ThemeContext.Provider value={value}>
      {inherit ? (
        content
      ) : (
        <div
          data-tu-theme={theme}
          data-tu-palette={palette}
          className={cn(
            'bg-background text-foreground',
            theme === 'dark' && 'dark',
            className,
          )}
          style={{ ...(tokens as CSSProperties | undefined), ...style }}
        >
          {content}
        </div>
      )}
    </ThemeContext.Provider>
  );
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge Tailwind classes with later ones winning - the same `cn` shadcn/ui
 * uses, so a consumer can override any class on any component by passing
 * `className`, with no specificity war.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Shared empty array, so a normalized-away prop keeps a stable identity and
 *  does not invalidate the `useMemo` that depends on it on every render. */
const EMPTY: readonly never[] = Object.freeze([]);

/**
 * Coerces a feed-supplied collection to something safe to iterate.
 *
 * A live feed is not a type system. Sockets drop fields, REST returns `null`
 * for "no rows yet", and a panel mounts before its first payload lands. None
 * of that should unmount the React tree — a component with nothing to show
 * renders its empty state instead. Returns a frozen shared array when the
 * input is unusable, so the identity stays stable across renders.
 */
export function toArray<T>(value: readonly T[] | null | undefined): readonly T[] {
  return Array.isArray(value) ? value : (EMPTY as readonly T[]);
}

/** `toArray` for both sides of a book, tolerating a missing snapshot entirely. */
export function toBook<T>(book: { bids?: readonly T[] | null; asks?: readonly T[] | null } | null | undefined) {
  return { bids: toArray(book?.bids), asks: toArray(book?.asks) };
}
